const items = $input.all();

if (!items.length) {
  throw new Error('No input items received');
}

const firstItem = items[0];

if (!firstItem.binary?.data) {
  throw new Error('No binary PDF found in property "data"');
}

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64String = buffer
  .toString('base64')
  .replace(/\s+/g, '');

let fileName = 'unknown.pdf';

try {
  fileName =
    firstItem.binary.data.fileName ||
    $('Google Drive Trigger').first().json.name ||
    'unknown.pdf';
} catch (e) {}

return [
  {
    json: {
      pdf_base64: base64String,
      file_name: fileName
    }
  }
];

let rawResponse = '';
let fileName = '';

// Get file name safely
try {
  fileName = $('Auth Letter detector').first().json.name || 'Unknown File';
} catch (e) {
  fileName = 'Unknown File';
}

// 1. Try Basic LLM Chain (text path)
try {
  const textOutput = $('Claude Parser').first().json.text;
  if (textOutput) rawResponse = textOutput;
} catch (e) {}

// 2. Try Anthropic Vision fallback
if (!rawResponse) {
  try {
    rawResponse = $('Anthropic Vision').first().json.content[0].text || '';
  } catch (e) {}
}

// 3. Handle no response
if (!rawResponse) {
  return [{
    json: {
      parse_error: true,
      error_message: 'No response from extraction',
      file_name: fileName,
      student_name: null,
      guardian_name: null,
      student_id: null,
      authorization_number: null,
      district: null,
      service_type: null,
      authorized_hours_per_month: null,
      start_date: null,
      end_date: null,
      case_manager_name: null,
      subject_areas: null,
      gross_auth_amount: null,
      notes: null,
      warnings: ['CRITICAL: No response — manual review required'],
      has_warnings: true
    }
  }];
}

// 4. Clean response (VERY IMPORTANT)
let cleaned = rawResponse
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

// 🔥 EXTRA FIX: remove leading "=" if present
if (cleaned.startsWith('=')) {
  cleaned = cleaned.slice(1);
}

// 5. Parse JSON safely
let extracted;

try {
  extracted = JSON.parse(cleaned);
} catch (e) {
  return [{
    json: {
      parse_error: true,
      error_message: 'Failed to parse response',
      raw_response: rawResponse,
      file_name: fileName,
      student_name: null,
      student_id: null,
      authorization_number: null,
      district: null,
      service_type: null,
      authorized_hours_per_month: null,
      start_date: null,
      end_date: null,
      case_manager_name: null,
      subject_areas: null,
      gross_auth_amount: null,
      notes: null,
      warnings: ['CRITICAL: Could not parse response — manual review required'],
      has_warnings: true
    }
  }];
}

// 6. Validate required fields
const warnings = [];
const requiredFields = [
  'student_name',
  'student_id',
  'authorization_number',
  'start_date',
  'end_date',
  'authorized_hours_per_month',
];

requiredFields.forEach(field => {
  if (!extracted[field]) {
    warnings.push(`Missing required field: ${field}`);
  }
});

// 7. Format date
const today = new Date().toLocaleDateString('en-US', {
  month: '2-digit',
  day: '2-digit',
  year: '2-digit'
});

// 8. Build auth comment
const authComment = [
  `${today}: ${extracted.authorization_number || 'NO AUTH#'}`,
  extracted.service_type || '',
  extracted.authorized_hours_per_month
    ? `${extracted.authorized_hours_per_month} HRS/MO`
    : '',
  extracted.gross_auth_amount
    ? `GROSS AUTH AMT: ${extracted.gross_auth_amount}`
    : '',
  extracted.notes || ''
].filter(Boolean).join('. ');

// 9. Build service date
const serviceDate = extracted.start_date && extracted.end_date
  ? `${extracted.start_date} - ${extracted.end_date}`
  : null;

// 10. Format hours per month
const hoursPerMonth = extracted.authorized_hours_per_month && serviceDate
  ? `${extracted.authorized_hours_per_month} hours/month (${serviceDate})`
  : extracted.authorized_hours_per_month
  ? `${extracted.authorized_hours_per_month} hours/month`
  : null;

// 11. Final output
return [{
  json: {
    ...extracted,
    auth_comment: authComment,
    service_date: serviceDate,
    hours_per_month_formatted: hoursPerMonth,
    file_name: fileName,
    warnings: warnings,
    has_warnings: warnings.length > 0,
    processed_at: today,
    parse_error: false
  }
}];

const targetRaw = $('Parse and Validate Result').first().json.student_name;

if (!targetRaw) {
  throw new Error('student_name is missing from Parse and Validate node');
}

const target = targetRaw.toLowerCase().trim();
const rows = $input.all();

const match = rows.find(item => {
  const name = item.json.Student?.toLowerCase().trim();
  return name === target;
});

if (match) {
  return [{
    json: {
      ...match.json,
      row_found: true
    }
  }];
}

return [{
  json: {
    row_found: false
  }
}];

const parsed = $('Parse and Validate Result').first().json;
const row = $input.first().json;

const existingComments = row['Authorization Comments'] || '';
const newAuthComment = parsed.auth_comment || '';
const combinedComments = existingComments
  ? `${existingComments}\n${newAuthComment}`
  : newAuthComment;

const auth1 = row['Contract Service Date 1st Auth'];
const auth2 = row['2nd Authorization'];
const auth3 = row['3rd Authorization'];
const auth4 = row['4th Authorization'];

let authColumnToUpdate = null;

if (!auth1) {
  authColumnToUpdate = 'Contract Service Date 1st Auth';
} else if (!auth2) {
  authColumnToUpdate = '2nd Authorization';
} else if (!auth3) {
  authColumnToUpdate = '3rd Authorization';
} else if (!auth4) {
  authColumnToUpdate = '4th Authorization';
}

const fileName = (parsed.file_name || '').toLowerCase();
const notes = (parsed.notes || '').toLowerCase();
const serviceType = (parsed.service_type || '').toLowerCase();

const looksLikeDocument = fileName.endsWith('.pdf');
const looksLikePos =
  fileName.includes('pos') ||
  notes.includes('pos') ||
  serviceType.includes('authorization');

const authorizationStatus = (looksLikeDocument || looksLikePos)
  ? 'Received'
  : 'Approved';

// Force text values for Sheets
const textComment = combinedComments ? `'${String(combinedComments)}` : '';
const textServiceDate = parsed.service_date ? `'${String(parsed.service_date)}` : '';
const textHours = parsed.hours_per_month_formatted ? `'${String(parsed.hours_per_month_formatted)}` : '';
const textStatus = authorizationStatus ? `'${String(authorizationStatus)}` : '';
const textAreas = parsed.subject_areas ? `'${String(parsed.subject_areas)}` : '';
let formattedScName = '';

if (parsed.case_manager_name) {
  const raw = parsed.case_manager_name.trim();

  if (raw.includes(',')) {
    const [last, first] = raw.split(',').map(s => s.trim());
    formattedScName = `${first} ${last}`;
  } else {
    formattedScName = raw;
  }
}

const textScName = formattedScName ? `'${formattedScName}` : '';
const textEndDate = parsed.end_date ? `'${String(parsed.end_date)}` : '';

const updatePayload = {
  row_number: row.row_number,
  authorization_comments: textComment,
  current_auth_expiration_date: textEndDate,
  hours_per_month: textHours,
  authorization_status: textStatus,
  areas_of_support: textAreas,
  sc_name: textScName,
  auth_column_to_update: authColumnToUpdate,
  auth_column_value: textServiceDate,
  has_overflow_warning: !authColumnToUpdate && !!parsed.service_date
};

const warnings = [...(parsed.warnings || [])];
if (!authColumnToUpdate && parsed.service_date) {
  warnings.push('All authorization date columns are filled; manual review required for additional authorization entry');
}

return [{
  json: {
    ...row,
    ...parsed,
    updatePayload,
    warnings,
    has_warnings: warnings.length > 0
  }
}];

const parsed = $('Parse and Validate Result').first().json;

const fileName = (parsed.file_name || '').toLowerCase();
const notes = (parsed.notes || '').toLowerCase();
const serviceType = (parsed.service_type || '').toLowerCase();

const looksLikeDocument = fileName.endsWith('.pdf');
const looksLikePos =
  fileName.includes('pos') ||
  notes.includes('pos') ||
  serviceType.includes('authorization');

const authorizationStatus = (looksLikeDocument || looksLikePos)
  ? 'Received'
  : 'Approved';

// Format SC name: LAST, FIRST -> First Last
let formattedScName = '';
if (parsed.case_manager_name) {
  const raw = parsed.case_manager_name.trim();
  if (raw.includes(',')) {
    const [last, first] = raw.split(',').map(s => s.trim());
    formattedScName = `${first} ${last}`;
  } else {
    formattedScName = raw;
  }
}

// Force text values for Google Sheets
const textStudent = parsed.student_name ? `'${String(parsed.student_name)}` : '';
const textComments = parsed.auth_comment ? `'${String(parsed.auth_comment)}` : '';
const textAuth1 = parsed.service_date ? `'${String(parsed.service_date)}` : '';
const textEndDate = parsed.end_date ? `'${String(parsed.end_date)}` : '';
const textHours = parsed.hours_per_month_formatted ? `'${String(parsed.hours_per_month_formatted)}` : '';
const textStatus = authorizationStatus ? `'${String(authorizationStatus)}` : '';
const textAreas = parsed.subject_areas ? `'${String(parsed.subject_areas)}` : '';
const textScName = formattedScName ? `'${String(formattedScName)}` : '';

return [{
  json: {
    ...parsed,
    newRowPayload: {
      uci: parsed.student_id || '',
      student: textStudent,
      authorization_comments: textComments,
      auth_1: textAuth1,
      auth_2: '',
      auth_3: '',
      auth_4: '',
      current_auth_expiration_date: textEndDate,
      hours_per_month: textHours,
      authorization_status: textStatus,
      areas_of_support: textAreas,
      sc_name: textScName
    }
  }
}];
